import numpy as np, json
from helper import load, cmask

a = load('fig_015.png')
d = json.load(open('f15_tmpl.json'))
# consensus grid: merge colored detections with tol 4, then merge near-dups (>=4.5 px) that both sides support
xs = np.concatenate([np.array(v)[:,0] for v in d.values() if isinstance(v[0], list)])
xs = np.sort(xs)
cl=[]
for x in xs:
    if cl and x-cl[-1][-1] <= 4: cl[-1].append(x)
    else: cl.append([x])
grid=[float(np.mean(g)) for g in cl]
# merge close grid points if no series has a detection uniquely in the gap
grid2=[]
for g in grid:
    if grid2 and g-grid2[-1] < 8:
        # check support: any detection in [grid2[-1], g]
        grid2.append(g)  # keep separate for now
    else:
        grid2.append(g)
grid=grid2
print('grid n=',len(grid))

LEG = (392,615,205,415)
def inleg(x,y):
    return LEG[0]<=x<=LEG[1] and LEG[2]<=y<=LEG[3]

colors = {'red':(237,45,55),'green':(76,175,80),'blue':(60,90,170),'purple':(188,92,158)}
masks = {c: cmask(a, ref, 70) for c, ref in colors.items()}
# remove legend from masks
for m in masks.values():
    m[LEG[2]:LEG[3], LEG[0]:LEG[1]] = False

out={}
for c, m in masks.items():
    res=[]
    for gx in grid:
        x0=int(gx-3); x1=int(gx+3)+1
        col = m[45:399, x0:x1]
        rows = np.where(col.any(axis=1))[0]
        if len(rows)==0:
            res.append((round(gx,1), None, 0)); continue
        # cluster rows with gap>3
        clusters=[]
        for r in rows:
            if clusters and r-clusters[-1][-1] <= 3: clusters[-1].append(r)
            else: clusters.append([r])
        best=None
        for clu in clusters:
            yc = 45 + (clu[0]+clu[-1])/2
            h = clu[-1]-clu[0]+1
            n = int(col[clu[0]:clu[-1]+1].sum())
            if best is None or abs(yc-190) < abs(best[2]-190): best=(clu[0]+45, clu[-1]+45, yc, n, h)
        res.append((round(gx,1), round((best[2] if best else 0),1), best[3] if best else 0, best[4] if best else 0))
    out[c]=res

for c in colors:
    miss=[r for r in out[c] if r[2]==0]
    thin=[r for r in out[c] if 0<r[2]<12]
    print(f'== {c}: missing {len(miss)} at {[r[0] for r in miss]}, thin(<12px) {len(thin)} at {[(r[0],r[1],r[2]) for r in thin]}')
json.dump(out, open('s15d.json','w'))
